1	package cli
2	
3	import (
4		"context"
5		"crypto/sha256"
6		"encoding/hex"
7		"encoding/json"
8		"errors"
9		"fmt"
10		"net/url"
11		"os"
12		"path/filepath"
13		"regexp"
14		"slices"
15		"strconv"
16		"strings"
17	
18		"github.com/entireio/entire-brain/internal/config"
19	)
20	
21	const (
22		envCLIVersion      = "ENTIRE_CLI_VERSION"
23		envRepoRoot        = "ENTIRE_REPO_ROOT"
24		envPluginConfigDir = "ENTIRE_PLUGIN_CONFIG_DIR"
25		envPluginDataDir   = "ENTIRE_PLUGIN_DATA_DIR"
26		envPluginStateDir  = "ENTIRE_PLUGIN_STATE_DIR"
27		envPluginCacheDir  = "ENTIRE_PLUGIN_CACHE_DIR"
28	
29		xdgConfigHome = "XDG_CONFIG_HOME"
30		xdgDataHome   = "XDG_DATA_HOME"
31		xdgStateHome  = "XDG_STATE_HOME"
32		xdgCacheHome  = "XDG_CACHE_HOME"
33	
34		xdgRootDir        = "entire"
35		repoStoreDirName  = "repos"
36		brainHeadFileName = "head.json"
37	
38		// pluginDataName is this plugin's namespace under the host's plugin data
39		// root. The host dispatches the brain with ENTIRE_PLUGIN_DATA_DIR set to
40		// <xdg_data>/entire/plugins/data/brain; run standalone (dev), we mirror that
41		// suffix so the binary targets the real brain store, not a shadow one.
42		pluginDataName = "brain"
43	)
44	
45	var repoKeyUnsafeChars = regexp.MustCompile(`[^a-zA-Z0-9._-]+`)
46	var repoRemoteSCPRegex = regexp.MustCompile(`^(?:[^@]+@)?([^:/]+):(.+)$`)
47	var knownRepoDomainSlugs = map[string]string{
48		"github.com":    "gh",
49		"gitlab.com":    "gl",
50		"bitbucket.org": "bb",
51		"entire.io":     "et",
52		"tangled.org":   "tg",
53		"code.storage":  "cs",
54	}
55	
56	// EntireEnv captures the environment variables supplied by the parent Entire
57	// CLI when this binary is dispatched as an external command.
58	type EntireEnv struct {
59		CLIVersion      string
60		RepoRoot        string
61		PluginConfigDir string
62		PluginDataDir   string
63		PluginStateDir  string
64		PluginCacheDir  string
65	}
66	
67	func EnvFromOS() EntireEnv {
68		return EntireEnv{
69			CLIVersion: os.Getenv(envCLIVersion),
70			// Keep the host-supplied spelling. Storage identity canonicalization is
71			// intentionally local to repoStoragePaths; retaining an ambient hidden
72			// alias here would leak repo A into per-repo Options copies for repo B.
73			RepoRoot:        os.Getenv(envRepoRoot),
74			PluginConfigDir: os.Getenv(envPluginConfigDir),
75			PluginDataDir:   os.Getenv(envPluginDataDir),
76			PluginStateDir:  os.Getenv(envPluginStateDir),
77			PluginCacheDir:  os.Getenv(envPluginCacheDir),
78		}
79	}
80	
81	type pluginDirs struct {
82		Config string
83		Data   string
84		State  string
85		Cache  string
86	}
87	
88	func resolvePluginDirs(env EntireEnv) (pluginDirs, error) {
89		configDir, err := resolveXDGDir(env.PluginConfigDir, envPluginConfigDir, xdgConfigHome, filepath.Join(".config", xdgRootDir))
90		if err != nil {
91			return pluginDirs{}, fmt.Errorf("resolve plugin config dir: %w", err)
92		}
93		dataDir, err := resolveXDGDir(env.PluginDataDir, envPluginDataDir, xdgDataHome, filepath.Join(".local", "share", xdgRootDir))
94		if err != nil {
95			return pluginDirs{}, fmt.Errorf("resolve plugin data dir: %w", err)
96		}
97		if env.PluginDataDir == "" {
98			// No host-supplied data dir (standalone/dev run). Mirror the host's
99			// plugin-data layout — <xdg_data>/entire/plugins/data/brain — so the brain
100			// resolves to the same store the installed plugin uses rather than a shadow
101			// XDG store. Only the data dir is namespaced; the host leaves config/state/
102			// cache unset, so their XDG fallbacks already match.
103			dataDir = filepath.Join(dataDir, "plugins", "data", pluginDataName)
104		}
105		stateDir, err := resolveXDGDir(env.PluginStateDir, envPluginStateDir, xdgStateHome, filepath.Join(".local", "state", xdgRootDir))
106		if err != nil {
107			return pluginDirs{}, fmt.Errorf("resolve plugin state dir: %w", err)
108		}
109		cacheDir, err := resolveXDGDir(env.PluginCacheDir, envPluginCacheDir, xdgCacheHome, filepath.Join(".cache", xdgRootDir))
110		if err != nil {
111			return pluginDirs{}, fmt.Errorf("resolve plugin cache dir: %w", err)
112		}
113		return pluginDirs{
114			Config: configDir,
115			Data:   dataDir,
116			State:  stateDir,
117			Cache:  cacheDir,
118		}, nil
119	}
120	
121	func resolveXDGDir(pluginDir, pluginEnv, xdgEnv, homeFallback string) (string, error) {
122		if pluginDir != "" {
123			if !filepath.IsAbs(pluginDir) {
124				return "", fmt.Errorf("%s must be absolute, got %q", pluginEnv, pluginDir)
125			}
126			return pluginDir, nil
127		}
128		if xdg := os.Getenv(xdgEnv); xdg != "" {
129			if filepath.IsAbs(xdg) {
130				return filepath.Join(xdg, xdgRootDir), nil
131			}
132			// XDG says relative paths are invalid; ignore and fall back to HOME.
133		}
134		home, err := os.UserHomeDir()
135		if err != nil {
136			return "", fmt.Errorf("resolve home dir: %w", err)
137		}
138		return filepath.Join(home, homeFallback), nil
139	}
140	
141	type repoStorage struct {
142		Key      string
143		BrainDir string
144		HeadPath string
145	}
146	
147	const localRepoIdentityConflictCode = "repo_identity_conflict"
148	
149	// localRepoIdentityConflictError refuses to guess when an upgrade finds state
150	// under both the canonical root identity and the exact pre-upgrade lexical
151	// alias identity. Choosing either would hide the other repository history.
152	type localRepoIdentityConflictError struct {
153		Canonical repoStorage
154		Legacy    repoStorage
155	}
156	
157	// Error names the command that resolves the conflict.
158	//
159	// It used to end with "move one brain/head store aside and retry" -- a manual
160	// filesystem instruction with nothing behind it. Since every repo-scoped
161	// command refuses while the conflict stands, and that includes the deletes a
162	// reader would reach for, the message was the ONLY thing standing between the
163	// user and a dead repository, and it pointed at `mv`. Naming a command that
164	// exists is the difference between a diagnosis and a recovery path.
165	func (e *localRepoIdentityConflictError) Error() string {
166		return fmt.Sprintf(
167			"%s: state exists for canonical local repo key %q and pre-upgrade alias key %q; "+
168				"run `%s repo-identity` to see both stores, then `%s repo-identity --keep <repo-key>` "+
169				"to keep one and move the other aside (canonical brain: %s; legacy brain: %s)",
170			localRepoIdentityConflictCode,
171			e.Canonical.Key,
172			e.Legacy.Key,
173			setupCommandPrefix(os.LookupEnv),
174			setupCommandPrefix(os.LookupEnv),
175			e.Canonical.BrainDir,
176			e.Legacy.BrainDir,
177		)
178	}
179	
180	type repoStorageIdentity struct {
181		// Key is the identity every spelling of the same repository root must
182		// agree on: the root with EVERY path component resolved through symlinks.
183		//
184		// It used to be the caller's lexical spelling, which made the key a
185		// property of HOW the repository was addressed rather than of WHICH
186		// repository it is. A relative invocation from inside the working tree can
187		// only ever produce the physical spelling (git and the getcwd syscall both
188		// report it), while an absolute ENTIRE_REPO_ROOT keeps whatever the caller
189		// typed -- so on any host where a repository is reachable through a
190		// symlinked ancestor (macOS /tmp -> /private/tmp being the everyday case)
191		// the two routes minted two keys, built two brains, and then refused every
192		// command with a repo_identity_conflict once both existed. Only the fully
193		// resolved root is the same string no matter which route asked.
194		Key string
195	
196		// AlternateKeys are the other spellings of this same root that an earlier
197		// build may already have keyed this repository's brain under: the lexical
198		// spelling the caller supplied, and the spelling with only the root's final
199		// component resolved (the pre-fix canonical form). They are not separate
200		// repositories -- they are the same directory under a different name -- so
201		// an existing brain found under one of them is adopted in place rather than
202		// orphaned, and state under more than one is reported rather than guessed.
203		AlternateKeys []string
204	
205		Local bool
206	}
207	
208	// repoStorageSet is every store one repository could be using: the canonical
209	// one its identity names, and every spelling of that same root that currently
210	// holds state.
211	//
212	// It exists so the repair paths -- the ones whose whole job is to clear a
213	// duplicate store -- can see the duplicate instead of being refused by it.
214	// repoStoragePaths, which every ordinary command uses, turns the same facts
215	// into the single store to read and write, or into the refusal.
216	type repoStorageSet struct {
217		// Canonical is the store this repository's identity names, whether or not
218		// anything has been written there yet.
219		Canonical repoStorage
220		// Populated is every store holding state, canonical first when it holds
221		// any. More than one entry is the identity conflict.
222		Populated []repoStorage
223		// Local reports whether the identity came from the repository root's path
224		// (as opposed to a remote), which is the only case that can have
225		// alternates at all.
226		Local bool
227	}
228	
229	// Conflicted reports whether this repository's brain is split across more than
230	// one store.
231	func (s repoStorageSet) Conflicted() bool { return len(s.Populated) > 1 }
232	
233	// Active is the store ordinary commands read and write: the one established
234	// store when exactly one spelling holds state (adopted in place, so no files
235	// move), otherwise the canonical one.
236	func (s repoStorageSet) Active() repoStorage {
237		if len(s.Populated) == 1 {
238			return s.Populated[0]
239		}
240		return s.Canonical
241	}
242	
243	// conflictError renders the split as the refusal ordinary commands report.
244	func (s repoStorageSet) conflictError() error {
245		if !s.Conflicted() {
246			return nil
247		}
248		return &localRepoIdentityConflictError{Canonical: s.Populated[0], Legacy: s.Populated[1]}
249	}
250	
251	func resolveRepoStorageSet(ctx context.Context, runner CommandRunner, env EntireEnv, repoDir string) (repoStorageSet, error) {
252		return resolveRepoStorageSetWithSlug(ctx, runner, env, repoDir, repoDomainSlug)
253	}
254	
255	func resolveRepoStorageSetWithSlug(ctx context.Context, runner CommandRunner, env EntireEnv, repoDir string, slugForHost func(string, string) (string, error)) (repoStorageSet, error) {
256		dirs, err := resolvePluginDirs(env)
257		if err != nil {
258			return repoStorageSet{}, err
259		}
260		identity, err := resolveRepoStorageIdentityWithSlug(ctx, runner, dirs.Config, repoDir, repoDir, slugForHost)
261		if err != nil {
262			return repoStorageSet{}, err
263		}
264		brainRoot := filepath.Join(dirs.Data, repoStoreDirName)
265		canonical := repoStorageForKey(dirs, identity.Key)
266		if err := rejectBrainRootPathSymlinks(brainRoot, filepath.FromSlash(canonical.Key)); err != nil {
267			return repoStorageSet{}, err
268		}
269		set := repoStorageSet{Canonical: canonical, Local: identity.Local}
270		if !identity.Local {
271			return set, nil
272		}
273		canonicalExists, err := repoStorageContainsState(canonical)
274		if err != nil {
275			return repoStorageSet{}, err
276		}
277		if canonicalExists {
278			set.Populated = append(set.Populated, canonical)
279		}
280		for _, key := range identity.AlternateKeys {
281			alternate := repoStorageForKey(dirs, key)
282			if err := rejectBrainRootPathSymlinks(brainRoot, filepath.FromSlash(alternate.Key)); err != nil {
283				return repoStorageSet{}, err
284			}
285			exists, err := repoStorageContainsState(alternate)
286			if err != nil {
287				return repoStorageSet{}, err
288			}
289			if exists {
290				set.Populated = append(set.Populated, alternate)
291			}
292		}
293		return set, nil
294	}
295	
296	func repoStoragePaths(ctx context.Context, runner CommandRunner, env EntireEnv, repoDir string) (repoStorage, error) {
297		set, err := resolveRepoStorageSet(ctx, runner, env, repoDir)
298		if err != nil {
299			return repoStorage{}, err
300		}
301		// Refuse to guess whenever more than one spelling holds state: picking
302		// either would hide the other repository history. The refusal names the
303		// command that resolves it -- see localRepoIdentityConflictError.
304		if err := set.conflictError(); err != nil {
305			return repoStorage{}, err
306		}
307		// Otherwise preserve the exact established key in place. This is atomic
308		// because no files move, and it avoids a cross-root brain/head migration
309		// that could only be partially committed if the process or filesystem
310		// fails.
311		return set.Active(), nil
312	}
313	
314	func repoStorageForKey(dirs pluginDirs, key string) repoStorage {
315		return repoStorage{
316			Key:      key,
317			BrainDir: filepath.Join(dirs.Data, repoStoreDirName, filepath.FromSlash(key)),
318			HeadPath: filepath.Join(dirs.State, repoStoreDirName, filepath.FromSlash(key), brainHeadFileName),
319		}
320	}
321	
322	func repoStorageContainsState(storage repoStorage) (bool, error) {
323		for _, path := range []string{storage.BrainDir, storage.HeadPath} {
324			_, err := os.Lstat(path)
325			switch {
326			case err == nil:
327				return true, nil
328			case errors.Is(err, os.ErrNotExist):
329				continue
330			default:
331				return false, fmt.Errorf("inspect repo identity state %s: %w", path, err)
332			}
333		}
334		return false, nil
335	}
336	
337	// rejectReservedRepoKeySegment refuses a repo key whose first segment is
338	// reserved in the repo keyspace.
339	//
340	// "workspaces" is reserved: older builds stored workspace manifests at
341	// repos/workspaces/<name> (since relocated to a sibling of repos/), and a host
342	// slug or hand-edited DomainSlugs entry claiming the segment would collide with
343	// any legacy data still awaiting migration.
344	//
345	// This lives in one function because it is a property of the KEY, not of any one
346	// consumer of it. It used to be inline in brainDirForKey only, which left the two
347	// places that build a store path without that helper — `brain path`, and
348	// headPathForKey — accepting a key every other command refuses.
349	func rejectReservedRepoKeySegment(key string) error {
350		if first, _, _ := strings.Cut(key, "/"); first == workspaceDirName {
351			return fmt.Errorf("repo key uses the reserved %q segment: %s", workspaceDirName, key)
352		}
353		return nil
354	}
355	
356	func brainDirForKey(env EntireEnv, key string) (string, error) {
357		if err := rejectReservedRepoKeySegment(key); err != nil {
358			return "", err
359		}
360		dirs, err := resolvePluginDirs(env)
361		if err != nil {
362			return "", err
363		}
364		brainRoot := filepath.Join(dirs.Data, repoStoreDirName)
365		if err := rejectBrainRootPathSymlinks(brainRoot, filepath.FromSlash(key)); err != nil {
366			return "", err
367		}
368		return filepath.Join(brainRoot, filepath.FromSlash(key)), nil
369	}
370	
371	func headPathForKey(env EntireEnv, key string) (string, error) {
372		// Same guards as brainDirForKey. The head path is built from the same
373		// untrusted key and joined onto the same per-key directory, so accepting a
374		// key here that brainDirForKey refuses would put the two halves of a repo's
375		// storage under different rules.
376		if err := rejectReservedRepoKeySegment(key); err != nil {
377			return "", err
378		}
379		dirs, err := resolvePluginDirs(env)
380		if err != nil {
381			return "", err
382		}
383		headRoot := filepath.Join(dirs.State, repoStoreDirName)
384		if err := rejectBrainRootPathSymlinks(headRoot, filepath.FromSlash(key)); err != nil {
385			return "", err
386		}
387		return filepath.Join(headRoot, filepath.FromSlash(key), brainHeadFileName), nil
388	}
389	
390	func repoStorageKey(ctx context.Context, runner CommandRunner, configDir, repoDir string) (string, error) {
391		identity, err := resolveRepoStorageIdentity(ctx, runner, configDir, repoDir, repoDir)
392		if err != nil {
393			return "", err
394		}
395		return identity.Key, nil
396	}
397	
398	func resolveRepoStorageIdentity(ctx context.Context, runner CommandRunner, configDir, repoDir, legacyRepoDir string) (repoStorageIdentity, error) {
399		return resolveRepoStorageIdentityWithSlug(ctx, runner, configDir, repoDir, legacyRepoDir, repoDomainSlug)
400	}
401	
402	func resolveRepoStorageIdentityWithSlug(ctx context.Context, runner CommandRunner, configDir, repoDir, legacyRepoDir string, slugForHost func(string, string) (string, error)) (repoStorageIdentity, error) {
403		legacyRepoDir = filepath.Clean(legacyRepoDir)
404		rootLinkResolved, err := rootSymlinkResolvedLocalRepoDir(repoDir)
405		if err != nil {
406			return repoStorageIdentity{}, err
407		}
408		if runner != nil {
409			stdout, _, err := runner.Run(ctx, rootLinkResolved, "git", "remote", "get-url", "origin")
410			if err == nil {
411				if key, ok, keyErr := repoKeyFromRemoteWithSlug(configDir, strings.TrimSpace(string(stdout)), slugForHost); ok || keyErr != nil {
412					return repoStorageIdentity{Key: key}, keyErr
413				}
414			}
415		}
416		canonicalKey, err := localRepoStorageKey(rootLinkResolved)
417		if err != nil {
418			return repoStorageIdentity{}, err
419		}
420		identity := repoStorageIdentity{Key: canonicalKey, Local: true}
421		// The spellings this same root used to be keyed under, newest rule first:
422		// the final-component-resolved form (the pre-fix canonical), then the raw
423		// lexical form the caller supplied. Either may already hold the brain.
424		for _, spelling := range []string{rootLinkResolved, legacyRepoDir} {
425			key := localRepoStorageKeyForSpelling(spelling)
426			if key == identity.Key || slices.Contains(identity.AlternateKeys, key) {
427				continue
428			}
429			identity.AlternateKeys = append(identity.AlternateKeys, key)
430		}
431		return identity, nil
432	}
433	
434	// localRepoStorageKey is the ONE derivation of a local repository's storage key,
435	// and the only one any caller should use: the repository root with every path
436	// component resolved through symlinks, hashed.
437	//
438	// Full resolution is what makes the key a property of the repository rather
439	// than of the route taken to it. Every other spelling -- an absolute
440	// ENTIRE_REPO_ROOT through a symlinked ancestor, a `cd` through an alias, a
441	// relative invocation -- collapses onto this one, so a repository cannot end up
442	// with two brains and then be locked out of both.
443	//
444	// The deliberate error path: EvalSymlinks fails on a path that does not exist
445	// yet, and workspace manifests carry exactly such paths as durable hints for
446	// checkouts that are not present. A missing root therefore keeps its lexical
447	// spelling and no error. Any OTHER failure -- a resolution loop, an unreadable
448	// ancestor, a network mount that is up enough to stat but not to walk -- is
449	// REPORTED rather than silently degraded to the lexical spelling: degrading
450	// would mint exactly the second key this function exists to prevent, and the
451	// brain the repository already has would be invisible until the mount came
452	// back, at which point both would exist and every command would refuse.
453	func localRepoStorageKey(repoDir string) (string, error) {
454		root, err := canonicalLocalRepoRoot(repoDir)
455		if err != nil {
456			return "", err
457		}
458		return localRepoStorageKeyForSpelling(root), nil
459	}
460	
461	// localRepoStorageKeyForSpelling hashes the spelling it is handed, verbatim.
462	// It is for ALTERNATE identities only -- the historical spellings a brain may
463	// already be stored under. Deriving the identity of a repository with it is the
464	// defect; use localRepoStorageKey.
465	func localRepoStorageKeyForSpelling(repoDir string) string {
466		return filepath.ToSlash(filepath.Join("local", localRepoKey(repoDir)))
467	}
468	
469	// canonicalLocalRepoRoot resolves every component of a repository root. See
470	// localRepoStorageKey for why, and for the error contract.
471	func canonicalLocalRepoRoot(repoDir string) (string, error) {
472		if repoDir == "" {
473			return "", nil
474		}
475		cleaned := filepath.Clean(repoDir)
476		resolved, err := filepath.EvalSymlinks(cleaned)
477		switch {
478		case err == nil:
479			return filepath.Clean(resolved), nil
480		case errors.Is(err, os.ErrNotExist):
481			// A root that is not here yet is a durable hint, not an identity to
482			// refuse; keep the caller's spelling so the hint still resolves to the
483			// same key when the checkout appears.
484			return cleaned, nil
485		default:
486			return "", fmt.Errorf("resolve local repo root %s: %w", cleaned, err)
487		}
488	}
489	
490	// rootSymlinkResolvedLocalRepoDir resolves only a symlink in the repository
491	// root's FINAL path component.
492	//
493	// This was the canonical identity until full resolution replaced it, and it is
494	// kept for exactly two jobs. It is the directory git is invoked in, so a
495	// repository addressed through an alias is interrogated at its target. And it
496	// is one of the alternate key spellings a brain may already be stored under --
497	// see repoStorageIdentity.AlternateKeys -- which is why the rule it implements
498	// must not drift: an old store is only found again if this reproduces the
499	// spelling that created it.
500	//
501	// Missing paths remain untouched because workspace manifests use them as
502	// durable hints that may become available again later. Broken final-component
503	// links likewise retain the original hint until their targets exist.
504	func rootSymlinkResolvedLocalRepoDir(repoDir string) (string, error) {
505		if repoDir == "" {
506			return "", nil
507		}
508		original := filepath.Clean(repoDir)
509		current := original
510		const maxRootSymlinkDepth = 40
511		seen := make(map[string]struct{}, 1)
512		for depth := 0; depth < maxRootSymlinkDepth; depth++ {
513			if _, ok := seen[current]; ok {
514				return "", fmt.Errorf("resolve local repo root symlinks: cycle at %q", current)
515			}
516			seen[current] = struct{}{}
517	
518			info, err := os.Lstat(current)
519			if err == nil && info.Mode()&os.ModeSymlink == 0 {
520				return current, nil
521			}
522			if errors.Is(err, os.ErrNotExist) {
523				return original, nil
524			}
525			if err != nil {
526				return "", fmt.Errorf("stat local repo root: %w", err)
527			}
528	
529			target, err := os.Readlink(current)
530			if err != nil {
531				return "", fmt.Errorf("read local repo root symlink: %w", err)
532			}
533			if !filepath.IsAbs(target) {
534				target = filepath.Join(filepath.Dir(current), target)
535			}
536			current = filepath.Clean(target)
537		}
538		return "", fmt.Errorf("resolve local repo root symlinks: exceeded %d links", maxRootSymlinkDepth)
539	}
540	
541	func repoKeyFromRemote(configDir, remote string) (string, bool, error) {
542		return repoKeyFromRemoteWithSlug(configDir, remote, repoDomainSlug)
543	}
544	
545	func repoKeyFromRemoteWithSlug(configDir, remote string, slugForHost func(string, string) (string, error)) (string, bool, error) {
546		remote = strings.TrimSpace(remote)
547		if parsed, err := url.Parse(remote); err == nil && strings.EqualFold(parsed.Scheme, "entire") {
548			if parsed.Hostname() == "" {
549				return "", false, nil
550			}
551			components := normalizeRepoPath(parsed.Path)
552			if len(components) < 3 {
553				return "", false, nil
554			}
555			key := strings.Join(components, "/")
556			if components[0] == workspaceDirName {
557				return "", true, fmt.Errorf("repo key uses the reserved %q segment: %s", workspaceDirName, key)
558			}
559			return key, true, nil
560		}
561	
562		host, repoPath, ok := parseRepoRemote(remote)
563		if !ok {
564			return "", false, nil
565		}
566		slug, err := slugForHost(configDir, host)
567		if err != nil {
568			return "", true, err
569		}
570		components := []string{slug}
571		components = append(components, repoPath...)
572		key := strings.Join(components, "/")
573		// Mint no key the store will not accept. The slug is generated as three
574		// letters, so this can only fire for a hand-edited DomainSlugs entry — the
575		// case brainDirForKey's reserved-segment refusal exists for. Catching it here
576		// reports the config that produced the key rather than failing later in
577		// whichever consumer happens to build a path first.
578		if err := rejectReservedRepoKeySegment(key); err != nil {
579			return "", true, err
580		}
581		return key, true, nil
582	}
583	
584	func parseRepoRemote(remote string) (string, []string, bool) {
585		remote = strings.TrimSpace(remote)
586		if remote == "" {
587			return "", nil, false
588		}
589	
590		var host string
591		var path string
592		if parsed, ok := parseURLRemote(remote); ok {
593			host = parsed.host
594			path = parsed.path
595		} else if match := repoRemoteSCPRegex.FindStringSubmatch(remote); len(match) == 3 {
596			if looksLikeWindowsDriveRemotePath(remote, match[2]) {
597				return "", nil, false
598			}
599			host = match[1]
600			path = match[2]
601		} else if before, after, ok := strings.Cut(remote, "/"); ok && before != "" && after != "" && strings.Contains(before, ".") {
602			host = before
603			path = after
604		} else {
605			return "", nil, false
606		}
607	
608		host = normalizeRepoHost(host)
609		components := normalizeRepoPath(path)
610		if host == "" || len(components) == 0 {
611			return "", nil, false
612		}
613		return host, components, true
614	}
615	
616	func looksLikeWindowsDriveRemotePath(remote, scpPath string) bool {
617		return looksLikeWindowsDrivePath(remote) &&
618			(strings.HasPrefix(scpPath, "/") || strings.Contains(scpPath, "\\") || !strings.Contains(scpPath, "/"))
619	}
620	
621	type parsedRemote struct {
622		host string
623		path string
624	}
625	
626	func parseURLRemote(remote string) (parsedRemote, bool) {
627		if !strings.Contains(remote, "://") {
628			return parsedRemote{}, false
629		}
630		parsed, err := url.Parse(remote)
631		if err != nil || parsed.Host == "" {
632			return parsedRemote{}, false
633		}
634		return parsedRemote{host: parsed.Hostname(), path: parsed.Path}, true
635	}
636	
637	func normalizeRepoHost(host string) string {
638		host = strings.TrimSpace(strings.ToLower(host))
639		if h, _, ok := strings.Cut(host, ":"); ok {
640			host = h
641		}
642		return strings.Trim(host, "[]")
643	}
644	
645	func normalizeRepoPath(path string) []string {
646		path = strings.TrimSpace(path)
647		path = strings.Trim(path, "/")
648		path = strings.TrimSuffix(path, ".git")
649		var components []string
650		for _, component := range strings.Split(path, "/") {
651			component = safeRepoPathComponent(strings.ToLower(component))
652			if component != "" {
653				components = append(components, component)
654			}
655		}
656		return components
657	}
658	
659	func repoDomainSlug(configDir, host string) (string, error) {
660		if slug, ok := knownRepoDomainSlugs[host]; ok {
661			return slug, nil
662		}
663	
664		var slug string
665		_, err := config.Update(configDir, func(cfg *config.Config) error {
666			if cfg.DomainSlugs == nil {
667				cfg.DomainSlugs = make(map[string]string)
668			}
669			if existing := cfg.DomainSlugs[host]; existing != "" {
670				slug = existing
671				return nil
672			}
673			slug = generateDomainSlug(host, cfg.DomainSlugs)
674			cfg.DomainSlugs[host] = slug
675			return nil
676		})
677		if err != nil {
678			return "", err
679		}
680		return slug, nil
681	}
682	
683	func generateDomainSlug(host string, existing map[string]string) string {
684		used := make(map[string]struct{}, len(existing))
685		for _, slug := range existing {
686			used[slug] = struct{}{}
687		}
688		for i := 0; ; i++ {
689			sum := sha256.Sum256([]byte(host + ":" + strconv.Itoa(i)))
690			slug := threeLetterSlug(sum)
691			if _, ok := used[slug]; !ok {
692				return slug
693			}
694		}
695	}
696	
697	func threeLetterSlug(sum [sha256.Size]byte) string {
698		n := int(sum[0])<<16 | int(sum[1])<<8 | int(sum[2])
699		var b [3]byte
700		for i := range b {
701			b[i] = byte('a' + n%26)
702			n /= 26
703		}
704		return string(b[:])
705	}
706	
707	func safeRepoPathComponent(value string) string {
708		value = strings.Trim(repoKeyUnsafeChars.ReplaceAllString(value, "-"), "-._")
709		return value
710	}
711	
712	// localRepoKey hashes one path spelling into a store directory name. It is the
713	// raw primitive: reach it through localRepoStorageKey (which resolves the root
714	// first, and is what a repository's identity is) or, for a historical spelling,
715	// localRepoStorageKeyForSpelling.
716	func localRepoKey(repoDir string) string {
717		repoDir = filepath.Clean(repoDir)
718		base := filepath.Base(repoDir)
719		base = safeRepoPathComponent(base)
720		if base == "" || base == "." || base == string(filepath.Separator) {
721			base = "repo"
722		}
723		sum := sha256.Sum256([]byte(repoDir))
724		return base + "-" + hex.EncodeToString(sum[:])[:12]
725	}
726	
727	func ensureDir(path string) error {
728		if path == "" {
729			return errors.New("directory path is empty")
730		}
731		if err := os.MkdirAll(path, 0o700); err != nil {
732			return err
733		}
734		return nil
735	}
736	
737	func valueOrUnset(value string) string {
738		if value == "" {
739			return "<unset>"
740		}
741		return value
742	}
743	
744	// lookupRepoDomainSlug reads an established binding without allocating one or
745	// quarantining malformed configuration. A getter must not redefine identity.
746	func lookupRepoDomainSlug(configDir, host string) (string, error) {
747		if slug, ok := knownRepoDomainSlugs[host]; ok {
748			return slug, nil
749		}
750		path, err := config.Path(configDir)
751		if err != nil {
752			return "", err
753		}
754		data, err := os.ReadFile(path)
755		if err != nil && !errors.Is(err, os.ErrNotExist) {
756			return "", fmt.Errorf("read host bindings: %w", err)
757		}
758		if err == nil {
759			var cfg config.Config
760			if err := json.Unmarshal(data, &cfg); err != nil {
761				return "", fmt.Errorf("read host bindings: %w", err)
762			}
763			if slug := cfg.DomainSlugs[host]; slug != "" {
764				return slug, nil
765			}
766		}
767		return "", fmt.Errorf("unresolved_repo_host: %q has no stored host binding; run setup or refresh in its checkout, or use path --ensure to allocate it", host)
768	}
